from fastapi import FastAPI, HTTPException, Response
from pydantic import BaseModel, Field

app = FastAPI()
_db: dict[int, dict] = {}
_next = {"id": 1}


class TodoIn(BaseModel):
    title: str = Field(min_length=1)
    done: bool = False


class TodoPatch(BaseModel):
    done: bool


@app.post("/todos", status_code=201)
def create(t: TodoIn):
    tid = _next["id"]
    _next["id"] += 1
    _db[tid] = {"id": tid, "title": t.title, "done": t.done}
    return _db[tid]


@app.get("/todos")
def list_todos():
    return list(_db.values())


def _get(tid):
    if tid not in _db:
        raise HTTPException(404, "no existe")
    return _db[tid]


@app.get("/todos/{tid}")
def get(tid: int):
    return _get(tid)


@app.patch("/todos/{tid}")
def patch(tid: int, p: TodoPatch):
    t = _get(tid)
    t["done"] = p.done
    return t


@app.delete("/todos/{tid}", status_code=204)
def delete(tid: int):
    _get(tid)
    del _db[tid]
    return Response(status_code=204)
